// ElvenHuntingZones returns the hunting grounds of the elven lands.
func ElvenHuntingZones() []HuntingZone {
	zones := make([]HuntingZone, len(elvenHuntingZones))
	copy(zones, elvenHuntingZones)

	return zones
}
